import csv,random
r=list(csv.DictReader(open('data/holdout_scores.csv')))
y=[int(x['churned']) for x in r]
n=len(y);print(n,sum(y),sum(y)/n)
def auc(s):
    o=sorted(range(n),key=lambda i:s[i]);rk=0;pos=0;tot=0
    for k,i in enumerate(o,1):
        if y[i]:tot+=k;pos+=1
    return (tot-pos*(pos+1)/2)/(pos*(n-pos))
S={m:[float(x[m]) for x in r] for m in('model_a_score','model_b_score')}
def topk(s,k=500):
    o=sorted(range(n),key=lambda i:-s[i])[:k];return o
for m,s in S.items():
    t=topk(s);print(m,'auc',round(auc(s),4),'p@500',sum(y[i] for i in t)/500, 'ties',n-len(set(s)))
    for k in(100,250,500,1000):print('  p@',k,sum(y[i] for i in topk(s,k))/k)
ta,tb=set(topk(S['model_a_score'])),set(topk(S['model_b_score']));print('overlap',len(ta&tb))
random.seed(0);d=[]
for _ in range(2000):
    idx=[random.randrange(n) for _ in range(n)]
    def p(s):
        o=sorted(idx,key=lambda i:-s[i])[:500];return sum(y[i] for i in o)
    d.append(p(S['model_a_score'])-p(S['model_b_score']))
d.sort();print('boot diff A-B hits@500 95%',d[50],d[1000],d[1950])
